        in.nextToken();
        int n = (int) in.nval;
        int[][] rooms = new int[n][];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            int k = (int) in.nval;
            rooms[i] = new int[k];
            for (int j = 0; j < k; j++) {
